#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;

    vector<vector<long long>> memo(n + 1, vector<long long>(n + 1, -1));
    memo[0][0] = 1;

    function<long long(int, int)> recursive_count = [&](int n, int h) {
        if (memo[n][h] != -1) {
            return memo[n][h];
        }
        if (n == 0) {
            return (long long)0;
        }
        if (h == 0) {
            return recursive_count(n, 1);
        }

        long long result = 0;
        for (int i = 0; i < n; ++i) {
            result += recursive_count(n - i - 1, 0) * recursive_count(i, h - 1);
            result += recursive_count(n - i - 1, h - 1) * recursive_count(i, 0);
            result -= recursive_count(n - i - 1, h - 1) * recursive_count(i, h - 1);
        }

        memo[n][h] = result;
        return result;
    };

    cout << recursive_count(n, h) << endl;
    return 0;
}
